// The Lord of the Rings LCG, print bleed. Generated by lotr-lcg-strange-eons-bleed-plugin.
useLibrary('extension');
function getName(){ return 'The Lord of the Rings LCG, print bleed'; }
function getDescription(){ return 'Print-ready LotR LCG components with a 12pt bleed in their frames.'; }
function getVersion(){ return 1.0; }
function initialize(){
	var game = Game.get('LRL');
	if( game == null ){
		Eons.log.warning("TheLordOfTheRingsLCG-Bleed can't find TheLordOfTheRingsLCG");
		return;
	}
	Language.getInterface().addStrings('TheLordOfTheRingsLCG-Bleed/text/interface');
	Language.getGame().addStrings('TheLordOfTheRingsLCG-Bleed/text/game');
	game.masterSettings.addSettingsFrom('TheLordOfTheRingsLCG-Bleed/bleed.settings');

	ClassMap.add('TheLordOfTheRingsLCG-Bleed/bleed.classmap');
}
